it's", "a,b", ";x",                                                                      "NULL", "null", "\t", "ǅ", "x" * 45, "Ünïcødé ✓", "  lead", "trail  ", 
"1.0", "1.00", "2024-01-01"]                                                    SPECIAL_DATES = ["2022-12-31", "2023-01-01", "2023-01-02", "2023-06-30", "2023-0
