def strip_comment(line):
    out, q = [], False
    for ch in line:
        if ch == "'":
            q = not q
        if ch == ";" and not q:
            break
        out.append(ch)
    return "".join(out)


def harvest(texts):
    lit = {"STR": set(), "INT": set(), "NUM": set(), "DATE": set()}
    for text in texts:
        for line in text.splitlines():
            code = strip_comment(line)
            for s in _STR_LIT.findall(code):
                lit["STR"].add(s.replace("''", "'"))
            for d in re.findall(r"#(\d{4}-\d{2}-\d{2})#", code):
                lit["DATE"].add(d)
            ops = code.split(None, 1)
            if len(ops) == 2 and not re.match(r"(?i)(left|substr|slice|topk)$", 
ops[0]):                                                                                        rest = _STR_LIT.sub("''", ops[1])
                for n in re.findall(r"(?<![\w.#'])-?\d+(?:\.\d+)?(?![\w.#-])", r
est):                                                                                               lit["NUM" if "." in n else "INT"].add(n)
