import sys,tempfile,collections,os; sys.path.insert(0,'.')
from evaluator import main as M, compare as C, vm
from concurrent.futures import ThreadPoolExecutor
w=tempfile.mkdtemp(); jobs=[]
for g in M.build_corpus(w,1,True):
    for p in g[3]+g[4]:
        pr=C.parse(open(p).read())
        if not C.output_ordered(pr): continue
        for nc in (False,True):
            t=C.instrument(pr,no_cut=nc); q=p+('.full' if nc else '.inst'); open(q,'w').write(t)
            for d in g[5]: jobs.append((p,q,d,nc))
def one(j):
    p,q,d,nc=j; a,_=vm.run(p,d); b,e=vm.run(q,d)
    if a is None: return 'skip'
    if b is None: return 'INSTERR '+e[:80]+' '+os.path.basename(p)
    n=a['ncols']; rb=[r[:n] for r in b['rows']]
    if nc: return 'ok' if len(rb)>=len(a['rows']) else 'FULL_SHORT '+os.path.basename(p)
    return 'ok' if rb==a['rows'] else 'MISMATCH '+os.path.basename(p)
with ThreadPoolExecutor(16) as ex: r=list(ex.map(one,jobs))
print(collections.Counter(x.split(' ')[0] for x in r)); print([x for x in r if x not in('ok','skip')][:6])"

